// rustc-type: compiler/rustc_middle/src/mir/coverage.rs:254 NodeFlowData
/// Data representing a view of some underlying graph, in which each node's
/// successors have been merged into a single "supernode".
///
/// The resulting supernodes have no obvious meaning on their own.
/// However, merging successor nodes means that a node's out-edges can all
/// be combined into a single out-edge, whose flow is the same as the flow
/// (execution count) of its corresponding node in the original graph.
///
/// With all node flows now in the original graph now represented as edge flows
/// in the merged graph, it becomes possible to analyze the original node flows
/// using techniques for analyzing edge flows.
export interface NodeFlowData<Node> {
  /// Maps each node to the supernode that contains it, indicated by some
  /// arbitrary "root" node that is part of that supernode.
  supernodes: Node[];
  /// For each node, stores the single supernode that all of its successors
  /// have been merged into.
  ///
  /// (Note that each node in a supernode can potentially have a _different_
  /// successor supernode from its peers.)
  succ_supernodes: Node[];
}
export function debug_NodeFlowData<Node>(v: NodeFlowData<Node>, f: Fmt, debug_Node: Debug<Node>): string {
  return debug_struct(f, "NodeFlowData", [
    ["supernodes", debug_vec(v.supernodes, f, debug_Node)],
    ["succ_supernodes", debug_vec(v.succ_supernodes, f, debug_Node)],
  ]);
}
export function clone_NodeFlowData<Node>(v: NodeFlowData<Node>, clone_Node: (v: Node) => Node): NodeFlowData<Node> {
  return {
    supernodes: v.supernodes.map(clone_Node),
    succ_supernodes: v.succ_supernodes.map(clone_Node),
  };
}
